class Solution {
  public long minCost(String s, int[] cost) {
    long[] byChar = new long[26];
    long total = 0, best = 0;
    for (int i = 0; i < s.length(); i++) {
      byChar[s.charAt(i) - 'a'] += cost[i];
      total += cost[i];
    }
    for (long v : byChar) best = Math.max(best, v);
    return total - best;
  }
}
